    const canvas = canvasRef.current,
      grid = gridRef.current;
    if (!canvas || !grid) return;
    const {
      w,
      h,
      cols,
      rows,
      dpr,
      tone,
      dyn,
      pitch,
      cosA,
      sinA
    } = grid;
    const ctx = canvas.getContext('2d');
    ctx.save();
    ctx.scale(dpr, dpr);
    ctx.clearRect(0, 0, w, h);
    const maxR = pitch * 0.46;
    const amp = 0.3 * drift;
    let uMin = Infinity,
      uMax = -Infinity,
      vMin = Infinity,
      vMax = -Infinity;
