    const g = geomRef.current,
      el = mediaRef.current;
    if (!g || !el) return false;
    const sw0 = el.videoWidth || el.naturalWidth || 0;
    const sh0 = el.videoHeight || el.naturalHeight || 0;
    if (!sw0 || !sh0) return false;
    const {
      z,
      ox,
      oy
    } = driftAt(t);
    const ir = sw0 / sh0,
      wr = g.w / g.h;
